(53,'Assassino','Outro','80',285,'{"tamanho": "Médio", "pv": 90, "desloc": 9.0, "atr": {"agi": 4, "for": 2, "int": 3, "pre": 3, "vig": 2}, "fort": 5, "refl": 10, "vont": 10, "ini": 15, "perc": 10, "pericias": [{"n": "Crime", "b": 10}, {"n": "Enganação", "b": 10}, {"n": "Furtividade", "b": 10}], "resist": "", "vuln": "", "sentidos": "", "ataques": [{"n": "Faca", "alc": "Corpo a corpo x2, crítico 19", "teste": 17, "dano": "1d4+11 corte"}, {"n": "Pistola", "alc": "À distância x2, Curto, crítico 16/x4", "teste": 15, "dano": "1d12+14 balístico"}], "habilidades": [{"n": "Evasão", "acao": "Passiva", "desc": "Quando sofre um ataque que permite um teste de Reflexos para reduzir o dano à metade, o assassino não sofre dano algum se passar."}, {"n": "Ataque Furtivo", "acao": "Livre", "desc": "Uma vez por rodada, o assassino causa +4d6 pontos de dano com ataques corpo a corpo, ou à distância em alcance curto, contra alvos desprevenidos ou que esteja flanqueando."}, {"n": "Mão na Boca", "acao": "Livre", "desc": "Quando faz um ataque corpo a corpo furtivo contra uma criatura desprevenida, o assassino pode fazer um teste de agarrar (teste 2O+15). Se agarrar a criatura, ela não poderá falar enquanto estiver agarrada."}, {"n": "Assassinar", "acao": "Movimento", "desc": "O assassino analisa uma criatura em alcance curto. Até o fim de seu próximo turno, seu primeiro Ataque Furtivo que causar dano a ela tem seus dados de dano extras dessa habilidade dobrados."}], "desc": "", "def": 26}'::jsonb),
(54,'Comandante Mercenário','Outro','120',285,'{"tamanho": "Médio", "pv": 145, "desloc": 6.0, "atr": {"agi": 3, "for": 3, "int": 2, "pre": 2, "vig": 3}, "fort": 10, "refl": 10, "vont": 5, "ini": 15, "perc": 10, "pericias": [{"n": "Intimidação", "b": 10}, {"n": "Tática", "b": 10}], "resist": "Balístico, corte, impacto e perfuração 5", "vuln": "", "sentidos": "", "ataques": [{"n": "Machete", "alc": "Corpo a corpo x2, crítico 19", "teste": 17, "dano": "1d6+15 corte"}, {"n": "Metralhadora", "alc": "À distância x2, Médio, crítico 19/x3", "teste": 17, "dano": "3d12+15 balístico"}], "habilidades": [{"n": "Sadismo", "acao": "Passiva", "desc": "Se o comandante mercenário causar dano em um inimigo, o próximo ataque dele recebe +O no teste de ataque e, se acertar, causa mais um dado de dano do mesmo tipo."}, {"n": "Ataque em Movimento", "acao": "Completa", "desc": "O chefe mercenário pode percorrer seu deslocamento e atacar em qualquer ponto durante o movimento. Ele pode fazer seus dois ataques corpo a corpo ou à distância."}, {"n": "Ordens", "acao": "Movimento", "desc": "O chefe mercenário grita ordens para seus aliados em alcance médio. Eles recebem +O em testes de perícia e causam mais um dado de dano do mesmo tipo até o fim da cena."}], "desc": "", "def": 29}'::jsonb),
