(62,'Enxame de Abelhas','Outro','10',288,'{"tamanho": "Médio", "pv": 10, "desloc": 3.0, "atr": {"agi": 1, "for": 0, "int": 0, "pre": 1, "vig": 0}, "fort": 0, "refl": 5, "vont": 0, "ini": 5, "perc": 5, "pericias": [], "resist": "", "vuln": "", "sentidos": "Visão na penumbra", "ataques": [], "habilidades": [{"n": "Deslocamento especial", "acao": "Passiva", "desc": "Voo 9m"}, {"n": "Enxame", "acao": "Passiva", "desc": "Um enxame é uma aglomeração de criaturas que agem em conjunto. Em termos de regras, pode entrar no espaço ocupado por um ser. No fim do seu turno, o enxame causa 2d6 pontos de dano de perfuração a qualquer ser em seu espaço, automaticamente. Um enxame é imune a manobras de combate e efeitos que afetam apenas uma criatura e não causam dano e sofre apenas metade do dano de ataques com armas. Porém, sofre 50% a mais de dano por efeitos de área."}, {"n": "Zumbido Nauseante", "acao": "Passiva", "desc": "Um ser que sofra dano do enxame de abelhas fica enjoado por 1 rodada (Fortitude DT 15 evita)."}], "desc": "", "def": 15}'::jsonb),
